import React, { useEffect, useState } from "react";
import axios from "../utils/axios";
import { Trash2 } from "lucide-react";
import toast from "react-hot-toast";

const AllExpenses = () => {
  const [expenses, setExpenses] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const fetchExpenses = async () => {
    try {
      const email = localStorage.getItem("email");
      const res = await axios.get("/api/expenses", {
        headers: { email },
      });
      const sorted = (Array.isArray(res.data) ? res.data : []).sort((a, b) => {
        const dateA = a.date ? new Date(a.date).getTime() : 0;
        const dateB = b.date ? new Date(b.date).getTime() : 0;
        return dateB - dateA;
      });
      setExpenses(sorted);
    } catch (err) {
      toast.error("Failed to fetch expenses.");
      console.error("Error fetching expenses:", err);
    }
  };

  useEffect(() => {
    fetchExpenses();
  }, []);

  const handleDelete = async (id) => {
    try {
      const email = localStorage.getItem("email");
      await axios.delete(`/api/expenses/${id}`, {
        headers: { email },
      });
      toast.success("Expense deleted!");
      fetchExpenses();
    } catch (err) {
      toast.error("Delete failed.");
    }
  };

  const totalPages = Math.max(1, Math.ceil(expenses.length / itemsPerPage));
  const startIndex = (currentPage - 1) * itemsPerPage;
  const currentItems = expenses.slice(startIndex, startIndex + itemsPerPage);

  return (
    <div className="ml-64 p-6">
      <h2 className="text-2xl font-semibold mb-4">All Expenses</h2>
      <div className="bg-white rounded-xl shadow p-4 overflow-x-auto">
        <table className="w-full table-auto border-collapse">
          <thead>
            <tr className="bg-gray-100 text-left">
              <th className="p-2">Budget</th>
              <th className="p-2">Description</th>
              <th className="p-2 text-right">Amount (RM)</th>
              <th className="p-2 text-right">Date</th>
              <th className="p-2 text-center">Action</th>
            </tr>
          </thead>
          <tbody>
            {currentItems.map((e) => (
              <tr key={e.id} className="border-t">
                <td className="p-2 whitespace-nowrap">
                  {e.budget?.icon && (
                    <span className="text-xl mr-1">{e.budget.icon}</span>
                  )}
                  {e.budget?.name || "-"}
                </td>
                <td className="p-2">{e.description}</td>
                <td className="p-2 text-right">RM {(e.amount || 0).toFixed(2)}</td>
                <td className="p-2 text-right">
                  {e.date
                    ? new Date(e.date).toLocaleDateString("ms-MY", {
                        year: "numeric",
                        month: "long",
                        day: "numeric",
                      })
                    : "-"}
                </td>
                <td className="p-2 text-center">
                  <button
                    onClick={() => handleDelete(e.id)}
                    className="text-red-500 hover:text-red-700"
                  >
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
            {currentItems.length === 0 && (
              <tr>
                <td colSpan="5" className="text-center text-gray-500 p-4">
                  No expenses found.
                </td>
              </tr>
            )}
          </tbody>
        </table>

        <div className="flex justify-between items-center mt-4">
          <button
            onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))}
            disabled={currentPage === 1}
            className="px-4 py-2 rounded bg-gray-200 hover:bg-gray-300 disabled:opacity-50"
          >
            Previous
          </button>
          <span className="text-sm text-gray-600">
            Page {currentPage} of {totalPages}
          </span>
          <button
            onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))}
            disabled={currentPage === totalPages}
            className="px-4 py-2 rounded bg-gray-200 hover:bg-gray-300 disabled:opacity-50"
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
};

export default AllExpenses;
